import { test } from "bun:test";

test("Crypto API - SHA-256", async () => {
  const cmd = `const data = new TextEncoder().encode("hello world");
  const hashBuffer = await crypto.subtle.digest("SHA-256", data);
  const hashArray = Array.from(new Uint8Array(hashBuffer));
  const hashHex = hashArray.map(b => b.toString(16).padStart(2, '0')).join('');
  console.log(hashHex);`;
  console.log(`bun -e "${cmd}"`);

  Bun.spawnSync(["bun", "-e", cmd], {
    stdout: "inherit",
    stderr: "inherit",
  });

  console.log("What: Generate a SHA-256 hash using the Web Crypto API.");
  console.log("How: Use crypto.subtle.digest().");
  console.log("Why: Standardized, high-performance cryptography.");
});

import { test } from "bun:test";

test("URLPattern API", async () => {
  const cmd = `const pattern = new URLPattern({ pathname: '/user/:id' });
  const url = new URL('https://example.com/user/123');
  const match = pattern.matcher(url);
  console.log('Match:', match ? 'Success' : 'Failure');
  if (match) {
    console.log('Params:', match.pathname.groups);
  }`;
  console.log(`bun -e "${cmd}"`);

  Bun.spawnSync(["bun", "-e", cmd], {
    stdout: "inherit",
    stderr: "inherit",
  });

  console.log("What: Match URLs against patterns.");
  console.log("How: Use the URLPattern API.");
  console.log("Why: Powerful and efficient URL matching for routing.");
});

import { test } from "bun:test";

test("CompressionStream API", async () => {
  const cmd = `const str = "This is a string to compress.";
  const stream = new Blob([str]).stream();
  const compressedStream = stream.pipeThrough(new CompressionStream('gzip'));
  const compressed_response = new Response(compressedStream);
  const compressed_bytes = await compressed_response.arrayBuffer();
  console.log('Compressed size:', compressed_bytes.byteLength);`;
  console.log(`bun -e "${cmd}"`);

  Bun.spawnSync(["bun", "-e", cmd], {
    stdout: "inherit",
    stderr: "inherit",
  });

  console.log("What: Compress data using CompressionStream.");
  console.log("How: Pipe a stream through a new CompressionStream('gzip').");
  console.log("Why: Standardized stream compression for efficient data transfer.");
});

import { test } from "bun:test";

test("BroadcastChannel API", async () => {
  const cmd = `const bc = new BroadcastChannel('test_channel');
  bc.postMessage('Hello from the other side!');
  bc.onmessage = (ev) => console.log('Received:', ev.data);
  // Give it a moment to receive the message
  await new Promise(r => setTimeout(r, 100));
  bc.close();`;
  console.log(`bun -e "${cmd}"`);

  Bun.spawnSync(["bun", "-e", cmd], {
    stdout: "inherit",
    stderr: "inherit",
  });

  console.log("What: Send messages to other scripts on the same origin.");
  console.log("How: Use the BroadcastChannel API.");
  console.log("Why: Easy way to communicate between different scripts/tabs.");
});

